style.css:
@-moz-document domain("open.spotify.com") {
/* Reset root layout */
  html, body {
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    height: 100% !important;
  }

  /* Spotify’s app root wrapper - the stable background anchor */
  .Root__top-container::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: url("https://i.imgur.com/5btRUAd.jpg") no-repeat center center fixed;
    background-size: cover;
    z-index: -1;
    opacity: 0.85;
    pointer-events: none;
  }

  /* Make all panels see-through */
  .Root__main-view,
  .main-view-container,
  .main-view-container__scroll-node,
  .main-view-container__scroll-node-child,
  .Root__now-playing-bar,
  .Root__top-bar,
  .main-topBar-container,
  .main-navBar-navBar,
  .main-trackList-trackList {
    background-color: transparent !important;
    backdrop-filter: blur(6px);
  }

  /* Highlight effects */
  .main-trackList-trackListRow:hover,
  .main-trackList-trackListRow.active {
    background-color: rgba(0, 255, 170, 0.15) !important;
  }

  .main-navBar-navBar a:hover,
  .main-type-mesto,
  .main-type-ballad {
    color: #00ffaa !important;
  }

  .control-button,
  .progress-bar__fg,
  .volume-bar__fg {
    background-color: #00ffaa !important;
  }

  /* Optional: Custom scrollbars */
  ::-webkit-scrollbar {
    width: 6px;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #00ffaa;
    border-radius: 10px;
  }
}
